type When struct {
	Cond Expr
	Value Expr
}

func WhenFromFbs(fbs *generated.When) *When {
	o := &When{}
	if fbsVal := fbs.Cond(nil); fbsVal != nil {
		o.Cond = *ExprFromFbs(fbsVal)
	}
	if fbsVal := fbs.Value(nil); fbsVal != nil {
		o.Value = *ExprFromFbs(fbsVal)
	}
	return o
}

// WhenFromBytes deserializes a When from size-prefixed FlatBuffer bytes.
